CREATE TABLE patients (
  patient_id INT,
  patient_name TEXT
);

INSERT INTO patients (patient_id, patient_name) VALUES
  (102, 'Bob Chen'),
  (103, 'Carol Davis');

CREATE TABLE trials (
  trial_id INT,
  trial_name TEXT,
  phase TEXT,
  status TEXT
);

INSERT INTO trials VALUES
  (1, 'Cardio-Alpha Trial', 'Phase II', 'ACTIVE'),
  (2, 'Neuro-Beta Study', 'Phase III', 'RECRUITING');

CREATE TABLE enrollments (
  enrollment_id INT,
  patient_id INT,
  trial_id INT
);

CREATE TABLE dosage_logs (
  log_id INT,
  patient_id INT,
  mg_administered REAL,
  log_timestamp TEXT
);

INSERT INTO adverse_events VALUES
  (1, 102, 'LOW', 'Mild nausea', '2024-02-10'),
  (2, 104, 'HIGH', 'Severe reaction', '2024-02-03');

SELECT p.patient_name, ae.severity, ae.description
FROM patients p
LEFT JOIN adverse_events ae ON p.patient_id = ae.patient_id;

SELECT * FROM patients WHERE patient_id IN (
  SELECT patient_id FROM adverse_events WHERE severity = 'HIGH'
);

WITH avg_dosage AS (
  SELECT patient_id, AVG(mg_administered) as avg_mg FROM dosage_logs GROUP BY patient_id
)
SELECT * FROM avg_dosage WHERE avg_mg > 60;

SELECT patient_id, log_timestamp, mg_administered,
  ROW_NUMBER() OVER (PARTITION BY patient_id ORDER BY log_timestamp) as session_num
FROM dosage_logs;

SELECT patient_id, mg_administered,
  SUM(mg_administered) OVER (PARTITION BY patient_id ORDER BY log_timestamp) AS running_total
FROM dosage_logs;
